test_suite:
test('returns a function', () => {
  const { result } = renderHook(() => useIdPrefix('form'));
  expect(typeof result.current).toBe('function');
});

test('generated IDs contain both prefix and suffix', () => {
  const { result } = renderHook(() => useIdPrefix('email'));
  const id = result.current('input');
  expect(id).toContain('email');
  expect(id).toContain('input');
});

test('different suffixes produce different IDs', () => {
  const { result } = renderHook(() => useIdPrefix('field'));
  const a = result.current('label');
  const b = result.current('input');
  expect(a).not.toBe(b);
});

test('same suffix always returns same ID', () => {
  const { result } = renderHook(() => useIdPrefix('field'));
  expect(result.current('label')).toBe(result.current('label'));
});

// __hidden__
test('returned function reference is stable across renders', () => {
  const { result, rerender } = renderHook(() => useIdPrefix('stable'));
  const first = result.current;
  rerender();
  expect(result.current).toBe(first);
});

solution:
import { useId, useCallback } from 'react';

export function useIdPrefix(prefix: string): (suffix: string) => string {
  const id = useId();
  return useCallback((suffix: string) => `${prefix}-${id}-${suffix}`, [prefix, id]);
}
